import java.util.PriorityQueue

class MedianFinder {
    private val small = PriorityQueue<Int>(compareByDescending { it })   // max heap
    private val large = PriorityQueue<Int>()                              // min heap

    fun addNum(num: Int) {
        // 1. push through the small heap, then move its largest to the large heap
        small.add(num)
        large.add(small.poll())
        // 2. rebalance so that small has the same size or one more
        if (large.size > small.size) {
            small.add(large.poll())
        }
    }

    fun findMedian(): Double =
        if (small.size > large.size) small.peek().toDouble()
        else (small.peek() + large.peek()) / 2.0
}
// addNum: O(log n)   findMedian: O(1)   Space: O(n)

import java.util.PriorityQueue

class MedianFinder2 {
    private val small = PriorityQueue<Int>(compareByDescending { it })
    private val large = PriorityQueue<Int>()

    fun addNum(num: Int) {
        if (small.isEmpty() || num <= small.peek()) small.add(num)
        else large.add(num)

        // rebalance
        if (small.size > large.size + 1) large.add(small.poll())
        else if (large.size > small.size) small.add(large.poll())
    }

    fun findMedian(): Double =
        if (small.size > large.size) small.peek().toDouble()
        else (small.peek() + large.peek()) / 2.0
}
// Same complexity, easier to extend with removals

import java.util.PriorityQueue

fun medianSlidingWindow(nums: IntArray, k: Int): DoubleArray {
    val small = PriorityQueue<Int>(compareByDescending { it })
    val large = PriorityQueue<Int>()
    val result = DoubleArray(nums.size - k + 1)

    fun median(): Double =
        if (k % 2 == 1) small.peek().toDouble()
        else small.peek().toDouble() / 2 + large.peek().toDouble() / 2

    // Simple version: PriorityQueue.remove(x) is O(k), fine for moderate k
    for (i in nums.indices) {
        // add the new number
        if (small.isEmpty() || nums[i] <= small.peek()) small.add(nums[i]) else large.add(nums[i])

        // remove the number leaving the window
        if (i >= k) {
            val out = nums[i - k]
            if (out <= small.peek()) small.remove(out) else large.remove(out)
        }
        // rebalance
        while (small.size > large.size + 1) large.add(small.poll())
        while (large.size > small.size) small.add(large.poll())

        if (i >= k - 1) result[i - k + 1] = median()
    }
    return result
}
// Time: O(n * k) because of remove(); use lazy deletion or two TreeMaps for O(n log k)
// Space: O(k)

import java.util.PriorityQueue

fun findMaximizedCapital(k: Int, w: Int, profits: IntArray, capital: IntArray): Int {
    // min heap: projects ordered by required capital
    val byCapital = PriorityQueue<Int>(compareBy { capital[it] })
    for (i in profits.indices) byCapital.add(i)
    // max heap: profits of affordable projects
    val byProfit = PriorityQueue<Int>(compareByDescending { it })

    var money = w
    repeat(k) {
        // move every affordable project into the profit heap
        while (byCapital.isNotEmpty() && capital[byCapital.peek()] <= money) {
            byProfit.add(profits[byCapital.poll()])
        }
        if (byProfit.isEmpty()) return money
        money += byProfit.poll()                       // take the most profitable one
    }
    return money
}
// Time: O((n + k) log n)   Space: O(n)

import java.util.PriorityQueue

fun maximumCapital(k: Int, w: Int, profits: IntArray, capital: IntArray): Int {
    val projects = profits.indices.sortedBy { capital[it] }     // sort by capital once
    val maxProfit = PriorityQueue<Int>(compareByDescending { it })
    var money = w
    var idx = 0
    repeat(k) {
        while (idx < projects.size && capital[projects[idx]] <= money) {
            maxProfit.add(profits[projects[idx]])
            idx++
        }
        if (maxProfit.isEmpty()) return money
        money += maxProfit.poll()
    }
    return money
}
// Time: O(n log n + k log n)   Space: O(n)

// Median of a stream where every value is between 0 and 100:
// a counting array gives O(100) per query with no heaps.
class MedianCounting {
    private val counts = IntArray(101)
    private var total = 0

    fun add(x: Int) { counts[x]++; total++ }

    fun median(): Double {
        fun kth(k: Int): Int {                 // k is 1-based
            var seen = 0
            for (v in 0..100) {
                seen += counts[v]
                if (seen >= k) return v
            }
            return -1
        }
        return if (total % 2 == 1) kth(total / 2 + 1).toDouble()
        else (kth(total / 2) + kth(total / 2 + 1)) / 2.0
    }
}
