import java.util.PriorityQueue

// Minimum number of rooms: one heap of end times is enough,
// but two heaps of sorted starts and ends also work:
fun minMeetingRooms(intervals: Array<IntArray>): Int {
    val starts = PriorityQueue<Int>()
    val ends = PriorityQueue<Int>()
    for ((s, e) in intervals) { starts.add(s); ends.add(e) }
    var rooms = 0
    var best = 0
    while (starts.isNotEmpty()) {
        if (starts.peek() < ends.peek()) {
            starts.poll()
            rooms++
            best = maxOf(best, rooms)
        } else {
            ends.poll()
            rooms--
        }
    }
    return best
}
// Time: O(n log n)   Space: O(n)

import java.util.PriorityQueue

fun maxPerformance(n: Int, speed: IntArray, efficiency: IntArray, k: Int): Int {
    val mod = 1_000_000_007L
    val order = (0 until n).sortedByDescending { efficiency[it] }   // best efficiency first
    val minSpeed = PriorityQueue<Int>()                              // keeps the k fastest
    var speedSum = 0L
    var best = 0L
    for (i in order) {
        minSpeed.add(speed[i])
        speedSum += speed[i]
        if (minSpeed.size > k) speedSum -= minSpeed.poll()          // drop the slowest
        best = maxOf(best, speedSum * efficiency[i])                // efficiency[i] is the minimum so far
    }
    return (best % mod).toInt()
}
// Time: O(n log n)   Space: O(n)

import java.util.PriorityQueue

// Track both the smallest and the largest of the current candidates.
fun minRangeOfK(lists: List<IntArray>): IntArray {
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })       // [value, list, index]
    var currentMax = Int.MIN_VALUE
    for ((i, list) in lists.withIndex()) {
        minHeap.add(intArrayOf(list[0], i, 0))
        currentMax = maxOf(currentMax, list[0])
    }
    var start = 0
    var end = Int.MAX_VALUE
    while (minHeap.size == lists.size) {
        val (value, li, idx) = minHeap.poll()
        if (currentMax - value < end - start) { start = value; end = currentMax }
        if (idx + 1 == lists[li].size) break
        val next = lists[li][idx + 1]
        minHeap.add(intArrayOf(next, li, idx + 1))
        currentMax = maxOf(currentMax, next)
    }
    return intArrayOf(start, end)
}
// Time: O(N log K)   Space: O(K)

import java.util.TreeMap

// A TreeMap of counts supports add, remove and k-th lookup in O(log n)
// (counting elements while walking the keys is O(distinct values)).
class SortedCounter {
    private val map = TreeMap<Int, Int>()
    var size = 0
        private set

    fun add(x: Int) { map[x] = (map[x] ?: 0) + 1; size++ }

    fun remove(x: Int) {
        val c = map[x] ?: return
        if (c == 1) map.remove(x) else map[x] = c - 1
        size--
    }

    fun kth(k: Int): Int {               // 1-based
        var seen = 0
        for ((value, count) in map) {
            seen += count
            if (seen >= k) return value
        }
        throw NoSuchElementException()
    }
}
